nta.declaration:
// Abstracted Timed Automata Model with dedicated SafetyShield Template.
// Coordinate shifted: Ego starts at 0m to prevent integer range faults.
// Scaled units: 1 unit = 1 millimeter (1e-3 meters).
// Time unit: 1 millisecond.

const int SCALE = 1000;
const int TOTAL_TIME = 20000;
const int CONTROL_PERIOD = 1;

// Scaled Constant Velocities (m/ms * SCALE)
const int EgoSpeed_scaled = 14;    // ~50 km/h mapped to mm/ms
const int OtherSpeed_scaled = 14;  // ~50 km/h mapped to mm/ms

// Explicitly bounded large integer types to satisfy UPPAAL verification constraints
typedef int[-2147483647, 2147483647] large_int;

// Shifted interval boundaries for the Ego car (Initial X = 0)
large_int x_pos_min = 0;
large_int x_pos_max = 0;
large_int y_pos_min = 1 * SCALE;
large_int y_pos_max = 1 * SCALE;

// Shifted Positions for surrounding cars (Relative to Ego Initial X = 300)
large_int rear_x_scaled = -200 * SCALE;
large_int slow_x_scaled = 300 * SCALE;

// Dynamic Safety envelope parameters updated by the Shield template
large_int front_shield_dist = 20 * SCALE;
large_int rear_shield_dist = 15 * SCALE;

// Track violation states explicitly
bool shield_violation = false;

// Over-approximated coordinate steps for each 1ms control interval (in mm)
int x_step_low = 14;
int x_step_high = 14;
int y_step_low = 0;
int y_step_high = 0;

// Dynamic Heading tracking partitioned intervals
int heading_zone = 0; // 0: Straight, 1: Shallow Left, 2: Steep Left

clock Time;

// Conservative interval lookup updating abstraction metrics
void updateZoneRates()
{
    if (heading_zone == 0) {       
        x_step_low  = 13;       
        x_step_high = 14;       
        y_step_low  = -1;        
        y_step_high = 1;         
    } else if (heading_zone == 1) { 
        x_step_low  = 12;       
        x_step_high = 14;       
        y_step_low  = 1;         
        y_step_high = 5;        
    } else {                       
        x_step_low  = 12;
        x_step_high = 14;
        y_step_low  = -5;
        y_step_high = 5;
    }
}
